import type { Plugin } from 'vite';

// The one source of the dashboard's security headers. Cloudflare Pages gets `_headers` emitted
// into the build; Amplify reads `customHttp.yml` from the repository root, so that file is
// committed and regenerated by `npm run headers`.

const SUPABASE_CLOUD_SOURCES = ['https://*.supabase.co', 'wss://*.supabase.co'];

/** Supabase Cloud is always allowed; a custom domain or self-hosted URL adds its own origin. */
export function connectSources(supabaseUrl: string | undefined): string[] {
  const sources = ["'self'", ...SUPABASE_CLOUD_SOURCES];

  if (!supabaseUrl) {
    return sources;
  }

  const url = new URL(supabaseUrl);

  if (url.protocol === 'https:' && url.hostname.endsWith('.supabase.co')) {
    return sources;
  }

  return [...sources, url.origin, `${url.protocol === 'https:' ? 'wss:' : 'ws:'}//${url.host}`];
}

export function securityHeaders(supabaseUrl: string | undefined): Array<[name: string, value: string]> {
  const contentSecurityPolicy = [
    "default-src 'self'",
    "script-src 'self'",
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: blob:",
    "font-src 'self' data:",
    "worker-src 'self' blob:",
    "manifest-src 'self'",
    `connect-src ${connectSources(supabaseUrl).join(' ')}`,
    "frame-ancestors 'none'",
    "base-uri 'self'",
    "object-src 'none'",
    "form-action 'self'",
    'upgrade-insecure-requests',
  ].join('; ');

  return [
    ['Content-Security-Policy', contentSecurityPolicy],
    ['X-Content-Type-Options', 'nosniff'],
    ['X-Frame-Options', 'DENY'],
    ['Referrer-Policy', 'strict-origin-when-cross-origin'],
    ['Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=(), usb=()'],
  ];
}

export function cloudflareHeadersFile(supabaseUrl: string | undefined): string {
  return ['/*', ...securityHeaders(supabaseUrl).map(([name, value]) => `  ${name}: ${value}`), ''].join('\n');
}

export function amplifyCustomHttpFile(supabaseUrl: string | undefined): string {
  // A JSON string is a valid YAML double-quoted scalar; only values YAML would misread need it.
  const yamlValue = (value: string) => (/['":#]/.test(value) ? JSON.stringify(value) : value);

  return [
    'customHeaders:',
    "  - pattern: '**'",
    '    headers:',
    ...securityHeaders(supabaseUrl).flatMap(([name, value]) => [`      - key: ${name}`, `        value: ${yamlValue(value)}`]),
    '',
  ].join('\n');
}

/** Emits Cloudflare Pages' `_headers` for the Supabase URL the build is configured with. */
export function cloudflareHeadersPlugin(): Plugin {
  let supabaseUrl: string | undefined;

  return {
    name: 'stackvitals-security-headers',
    apply: 'build',
    configResolved(config) {
      supabaseUrl = config.env.VITE_SUPABASE_URL;
    },
    generateBundle() {
      this.emitFile({ type: 'asset', fileName: '_headers', source: cloudflareHeadersFile(supabaseUrl) });
    },
  };
}
